do $$ declare p jsonb; ex jsonb; opt uuid; response jsonb; t uuid; r uuid; first_xp integer;
begin
 if public.is_admin() then raise exception 'Student unexpectedly admin'; end if;
 if (select role from public.profiles where id=auth.uid())<>'student' then raise exception 'Signup role injection succeeded'; end if;
 if exists(select 1 from public.lesson_progress where user_id<>auth.uid()) then raise exception 'Other student progress leaked'; end if;
 if exists(select 1 from public.xp_transactions where user_id<>auth.uid()) then raise exception 'Other student XP leaked'; end if;
 if exists(select 1 from public.user_achievements where user_id<>auth.uid()) then raise exception 'Other student achievements leaked'; end if;
 if exists(select 1 from public.forum_reports where reporter_id<>auth.uid()) then raise exception 'Other student report leaked'; end if;
 if exists(select 1 from public.exercise_options) or exists(select 1 from public.exam_question_options) or exists(select 1 from public.exam_questions) then raise exception 'Answer-key table leak'; end if;
 if exists(select 1 from public.moderation_history) then raise exception 'Audit history leaked'; end if;
 p:=public.get_lesson('a1-verb-to-be');
 if jsonb_path_exists(p,'$.**.is_correct') or jsonb_path_exists(p,'$.**.explanation') then raise exception 'Lesson answer-key payload leak'; end if;
 ex:=p->'exercises'->0;
 select (o->>'id')::uuid into opt from jsonb_array_elements(ex->'options') o where o->>'option_text'='are';
 response:=public.submit_exercise((ex->>'id')::uuid,opt);
 if (response->>'correct')::boolean is distinct from true then raise exception 'Correct exercise submission failed'; end if;
 if not exists(select 1 from public.lesson_progress where user_id=auth.uid() and lesson_id=(p->'lesson'->>'id')::uuid and status='completed') then raise exception 'Progress missing'; end if;
 select total_xp into first_xp from public.profiles where id=auth.uid();
 if first_xp<=0 then raise exception 'XP missing'; end if;
 response:=public.submit_exercise((ex->>'id')::uuid,opt);
 if (response->>'xp_awarded')::integer<>0 or (select total_xp from public.profiles where id=auth.uid())<>first_xp then raise exception 'XP replay duplicated'; end if;
 t:=public.create_forum_thread('RLS student report fixture','A synthetic message for report isolation verification.');
 r:=public.report_forum_content('thread',t,'Spam or advertising: fixture only');
 if not exists(select 1 from public.forum_reports where id=r and reporter_id=auth.uid()) then raise exception 'Own report not readable'; end if;
 if public.report_forum_content('thread',t,'Spam or advertising: retry')<>r then raise exception 'Duplicate report created'; end if;
 if (select count(*) from public.forum_reports)<>1 then raise exception 'Expected only one own report'; end if;
 p:=public.start_toefl_attempt();
 if jsonb_path_exists(p,'$.**.is_correct') or jsonb_path_exists(p,'$.**.explanation') then raise exception 'Exam answer-key payload leak'; end if;
end $$;
